p='crates/cli/src/feedback.rs'
s=open(p).read()
s=s.replace("""/// documented field in its documented shape, `data` an object when present (`docs/state.md`, "Diagnostic
/// logs"). Anything else is left out, as is an `extension_log` line: it is
/// the extension's own text, which Fiber cannot vouch for.""","""/// documented field in its documented shape (`docs/state.md`, "Diagnostic
/// logs"), `data` an object when present. Anything else is left out, as is
/// an `extension_log` line: it is the extension's own text, which Fiber
/// cannot vouch for.""")
a=s.index("/// The newest `limit` entries")
b=s.index("/// The hub's reportable lines")
s=s[:a]+"""/// The newest `limit` entries, oldest first, and how many were dropped.
/// Ties in `ts` keep the order the entries came in. Every `error` and
/// `warn` entry is kept before any other, newest first when they alone
/// pass `limit`.
fn newest(mut entries: Vec<Entry>, limit: usize) -> (Vec<Entry>, usize) {
    entries.sort_by_key(|entry| entry.ts);
    let total = entries.len();
    let priority = entries.iter().filter(|entry| entry.priority).count();
    let mut room_priority = limit;
    let mut room_other = limit.saturating_sub(priority);
    let mut kept = Vec::new();
    for entry in entries.into_iter().rev() {
        let room = if entry.priority {
            &mut room_priority
        } else {
            &mut room_other
        };
        if *room > 0 {
            *room -= 1;
            kept.push(entry);
        }
    }
    kept.reverse();
    let dropped = total - kept.len();
    (kept, dropped)
}

"""+s[b:]
s=s.replace("fn hub_entries(logs: &Path, now: u64, session: Option<&str>)","fn hub_entries(logs: &Path, now: u64, session: Option<&SessionId>)")
