s=s.replace(".strip_prefix(id)?",".strip_prefix(id.0.as_str())?")
s=s.replace("pub fn diagnostics(home: &Path, clock: &dyn clock::Clock, session: Option<&str>) -> String {","pub fn diagnostics(home: &Path, clock: &dyn clock::Clock, session: Option<&SessionId>) -> String {")
s=s.replace("""    if let Some(id) = session {
        out.push_str(&format!(""","""    if let Some(session) = session {
        let id = session.0.as_str();
        out.push_str(&format!(""")
s=s.replace("crash_reports(home, id)","crash_reports(home, session)")
s=s.replace("newest(lines, SESSION_LINES, true)","newest(lines, SESSION_LINES)")
s=s.replace("""    let (hub, _) = newest(hub_entries(&logs, now, session), HUB_LINES, false);
    let texts: Vec<String> = hub.into_iter().map(|line| line.text).collect();""","""    let mut hub = hub_entries(&logs, now, session);
