fn crash_reports(home: &Path, id: &str) -> Vec<(String, String)> {
    let Ok(entries) = fs::read_dir(home.join("crashes")) else {
        return Vec::new();
    };
    let mut found: Vec<(u128, String, PathBuf)> = entries
        .flatten()
        .filter_map(|entry| {
            let name = entry.file_name().into_string().ok()?;
