fn section(out: &mut String, title: &str, texts: &[String]) {
    out.push_str(&format!("### {title}\\n\\n"));
    if texts.is_empty() {
        out.push_str("None.\\n\\n");
    }
    for text in texts {
        out.push_str(&format!("```\\n{text}\\n```\\n\\n"));
