const BACKTRACE_MARKER: &str = "\\nstack backtrace:\\n";

/// One reportable diagnostic line.
struct Entry {
    ts: u64,
    /// An `error` or `warn` line, which the cap keeps before any other.
    priority: bool,
    session: Option<String>,
    /// The line as recorded.
    text: String,
