fn hub_entries(logs: &Path, now: u64, session: Option<&str>) -> Vec<Entry> {
    let mut entries = Vec::new();
    for name in ["hub.log.1", "hub.log"] {
        read_entries(&logs.join(name), "hub", &mut entries);
