    fields.get("message")?.as_str()?;
    if code == "extension_log" {
        return None;
    }
    let session = match fields.get("session_id") {
        Some(id) => Some(id.as_str()?.to_owned()),
        None => None,
    };
    Some(Entry {
        ts,
        priority: matches!(level, "error" | "warn"),
        session,
        text: line.trim_end().to_owned(),
    })
