            found.contains(&"oldest-error".to_owned()),
            count <= 500,
            "{count}"
        );
        assert_eq!(found.last().unwrap(), &(count - 1).to_string());
        assert!(!report.contains("earlier lines left out"), "{count}");
    }
}

