    let oldest = now.saturating_sub(HUB_WINDOW_MS);
    entries.retain(|entry| {
        entry.ts <= now
            && match (entry.session.as_deref(), session) {
                (None, _) => entry.ts >= oldest,
                (Some(recorded), Some(selected)) => recorded == selected,
                (Some(_), None) => false,
