fn newest(mut entries: Vec<Entry>, limit: usize, favour: bool) -> (Vec<Entry>, usize) {
    entries.sort_by_key(|entry| entry.ts);
    let total = entries.len();
    let priority = if favour {
        entries.iter().filter(|entry| entry.priority).count()
