fn crash_details(text: &str) -> String {
    let first = text.lines().next().unwrap_or("");
    match text.rfind(BACKTRACE_MARKER) {
        Some(at) => format!(
            "{first}\\n{}",
            text[at + BACKTRACE_MARKER.len()..].trim_end()
