fn leaky_files(setup: &Setup, id: &str) {
    let home = setup.home();
    fs::create_dir_all(home.join("logs")).unwrap();
    fs::create_dir_all(home.join("crashes")).unwrap();
    fs::create_dir_all(home.join("credentials")).unwrap();
