fn the_hub_cap_breaks_a_tie_at_the_edge_by_stream_order() {
    let home = Home::new();
    let now = now();
    home.put("logs/hub.log.1", &[hub(now, None, "rotated")]);
    home.put(
        "logs/hub.log",
