    session(&setup, &workspace, NEWER, 9, None);
    leaky_files(&setup, NEWER);
    fs::write(
        setup.home().join(format!("logs/tui-{OLDER}.log")),
        diagnostic("tui", Some(OLDER), "x", "older-session-line"),
