    let broken = log::sessions_dir(&setup.home(), &workspace).join(UNREADABLE);
    fs::create_dir_all(&broken).unwrap();
    fs::write(broken.join("events.jsonl"), "not json\\n").unwrap();
    // A prefix of a real session is not that session.
    session(&setup, &workspace, NEWER, 9, None);
    for id in [
        "s_00000000000000ff",
        DELEGATE,
        UNREADABLE,
        &NEWER[..NEWER.len() - 1],
    ] {
        let id = if id.len() == NEWER.len() {
            id.to_owned()
        } else {
            format!("{id}0")
        };
        let output = run(
