            &["feedback", "--session", &id, "the sound stopped"],
            None,
            None,
        );
        assert_eq!(
            output.status.code(),
            Some(1),
            "{id} stderr: {}",
            stderr_text(&output)
        );
        assert_eq!(stderr_text(&output), format!("fiber: No session `{id}`.\\n"));
        assert!(stdout_text(&output).is_empty());
