        "schema_version": 1, "seq": 0, "payload": payload});
    let prompt = json!({"kind": "user_message", "session_id": id, "ts": ts,
        "schema_version": 1, "seq": 1, "payload": {"text": MARKER}});
    fs::write(dir.join("events.jsonl"), format!("{first}\\n{prompt}\\n")).unwrap();
