    );
    assert_eq!(
        output.status.code(),
        Some(0),
        "stderr: {}",
        stderr_text(&output)
    );
    let path = report_path(&output);
    let report = fs::read_to_string(&path).unwrap();
    for kept in [
        "## Diagnostics",
        &format!("Session: {NEWER}"),
        &format!("fiber sessions export {NEWER}"),
        "kept-session-line",
        "kept-hub-line",
        "thread 'worker' panicked at crates/x/src/y.rs:3:9:",
        "0: kept_frame",
    ] {
